do $$ begin if current_database() !~ '^dorm_repair_v2_(dev|test(_[a-z0-9]+)?)$' then raise exception 'Unsafe E target'; end if; end $$;
create table public.private_image(id bigint generated by default as identity primary key,owner_id bigint not null references public.sys_user(id) on delete restrict,storage_key varchar(60) not null unique,content_type varchar(30) not null,width integer not null check(width>0),height integer not null check(height>0),byte_size bigint not null check(byte_size between 1 and 5242880),sha256 varchar(64) not null,state varchar(12) not null default 'STAGED' check(state in ('STAGED','BOUND','CANCELED')),bound_draft_id bigint references public.repair_draft(id) on delete restrict,created_at timestamptz not null default current_timestamp,check((state='BOUND')=(bound_draft_id is not null)));
create index ix_image_owner on public.private_image(owner_id,id);
create index ix_image_cleanup on public.private_image(state,created_at);
create table public.draft_revision_image(revision_id bigint not null references public.repair_draft_revision(id) on delete restrict,image_id bigint not null references public.private_image(id) on delete restrict,position integer not null check(position between 0 and 5),primary key(revision_id,position),unique(revision_id,image_id));
create trigger draft_image_immutable before update or delete on public.draft_revision_image for each row execute function public.immutable_draft_revision();
